    public static string ForArchetype(string archetype) => archetype switch
    {
        "living_room" or "lounge" or "man_cave" or "recreation" => Couch,
        "tv" => Tv,
        "kitchen" or "dining" => Food,
        "hallway" or "corridor" or "staircase"
